mapper.select:
SELECT DATE_FORMAT(pl.entry_time, '%Y-%m-%d') AS date, CONCAT( FLOOR(TIMESTAMPDIFF(MINUTE, pl.entry_time, pl.exit_time)/60), '시간 ', MOD(TIMESTAMPDIFF(MINUTE, pl.entry_time, pl.exit_time), 60), '분' ) AS duration, DATE_FORMAT(pl.entry_time,'%H:%i') AS startTime, DATE_FORMAT(pl.exit_time ,'%H:%i') AS endTime, CONCAT(DATE_FORMAT(pl.entry_time,'%H:%i'), ' - ', DATE_FORMAT(pl.exit_time,'%H:%i')) AS timeRange, m.car_number AS carNumber, IFNULL(pmt.total_fee, 0) AS fee, CASE WHEN pl.exit_time IS NULL THEN '이용중' ELSE '완료' END AS status FROM parking_log pl JOIN member m ON pl.member_id = m.member_id LEFT JOIN payment pmt ON pl.payment_id = pmt.payment_id WHERE m.member_id = #{memberId}
AND DATE(pl.entry_time) BETWEEN #{startDate} AND #{endDate}
ORDER BY pl.entry_time DESC
